//! 📝️ Actual original paged receiving keeps one explicit finite bank through source, output and closure.
use semio_framework_value::{paged::PagedUtf8,NativeDecodeControl,RetainedCloneGrant,RetainedCloneProgress,DslValue,retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
use semio_framework_value_native_owned::native_decoding::{NativeReceive,NativeReceiver};
use semio_framework_value_testing_allocator as _;
pub(crate) struct Wallet{left:RetainedCloneGrant,work:u64}
impl Wallet{
 pub(crate) fn new()->Self{let f:serde_json::Value=serde_json::from_str(include_str!("../🎟️work/📐️.json")).unwrap();let s=&f["stock"];Self{left:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},work:s["items"].as_u64().unwrap()}}
 pub(crate) fn grant(&self)->RetainedCloneGrant{assert!(self.work>0,"finite paged CPU stock exhausted");RetainedCloneGrant{maximum_items:self.left.maximum_items.min(1),..self.left}}
 pub(crate) fn debit(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.left));self.left.maximum_items=self.left.maximum_items.checked_sub(p.copied_items).unwrap();self.left.maximum_copy_bytes=self.left.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.left.maximum_capacity_bytes=self.left.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.left.maximum_release_bytes=self.left.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();self.work=self.work.checked_sub(work).expect("finite paged CPU stock exhausted");}
}
pub(crate) fn drain<T:RetireOwned>(value:T,wallet:&mut Wallet){let mut close=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("paged fixture closure"));for _ in 0..10000{if close.terminal_is_empty(){return}let g=wallet.grant();let result=close.step(g);let work=close.last_turn_work();let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,work);result.unwrap();}panic!("paged closure stalled")}
pub(crate) fn original(value:DslValue,wallet:&mut Wallet)->RetainedCloneSource<DslValue>{let turn=RetainedCloneSource::admit_owned(value,(),wallet.grant());let p=turn.result.as_ref().map(|(_,p)|*p).unwrap_or_else(|(e,_,_)|e.retained_progress());wallet.debit(p,turn.work);turn.result.unwrap_or_else(|_|panic!("original source admission")).0}
#[test]
fn original_paged_text_admits_exact_unicode_and_closes_every_partial_owner(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let text=row["text"].as_str().unwrap();assert_eq!(text.len(),row["bytes"].as_u64().unwrap()as usize);
  if row["maximum"]==1{let mut wallet=Wallet::new();let source=original(DslValue::String(text.into()),&mut wallet);let mut receiver=<PagedUtf8<1> as NativeReceive<DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut rejected=false;for _ in 0..40{let turn=receiver.advance(source.borrow(),&mut control,4096,wallet.grant());let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,turn.work);if turn.result.is_err(){rejected=true;break}}assert!(rejected);receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break}let turn=receiver.close_step(wallet.grant());let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,turn.work);turn.result.unwrap();}assert!(receiver.terminal_is_empty());drain(source,&mut wallet);continue}
  for cut in [0,1,4,40,4096]{let mut wallet=Wallet::new();let source=original(DslValue::String(text.into()),&mut wallet);let mut receiver=<PagedUtf8<4096> as NativeReceive<DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);
   for _ in 0..cut{if receiver.output_ready(){break}let d=receiver.demands(source.borrow(),4096).unwrap();let g=wallet.grant();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(source.borrow(),4096).unwrap(),d);}
    let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,g));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,turn.work);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));turn.result.unwrap();}
   if receiver.output_ready(){let turn=receiver.take(wallet.grant());let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();wallet.debit(p,turn.work);let(value,_)=turn.result.unwrap().unwrap();assert_eq!(value.to_string_owner(),text);assert_eq!(value.len(),text.len());assert_eq!(serde_json::to_string(&value.to_string_owner()).unwrap(),serde_json::to_string(text).unwrap());drain(value,&mut wallet);}
   receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break}let turn=receiver.close_step(wallet.grant());let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());wallet.debit(p,turn.work);turn.result.unwrap();}assert!(receiver.terminal_is_empty());drain(source,&mut wallet);
  }
 }
}
